// Droits fixes dans le code, jamais decides par l IA
const e = $('Appel outil').first().json;
const role = String(e.role || '').toLowerCase();
const P = { climatpro: '6hh423vJrW7RvQQg', equipe: '6hh423vw4vGgHFPw' };
const NOMS = { '6hh423vJrW7RvQQg': 'Laurent ClimatPro', '6hh423vw4vGgHFPw': 'Equipe' };
const n = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const tasks = (($input.first().json || {}).results) || [];
const estEntretien = t => (t.labels || []).includes('entretien') || /entretien|maintenance|contrat|revision|nettoyage/.test(n(t.content + ' ' + t.description));
// admin : memos Laurent ClimatPro + Equipe ; technicien : tout Equipe + les memos de Laurent partages avec lui (label a son prenom)
const nom = n(e.nom).trim();
let vis = tasks.filter(t => t.project_id === P.equipe || (t.project_id === P.climatpro && (role === 'admin' || (!!nom && (t.labels || []).includes(nom)))));
const theme = n(e.theme).trim();
if (theme && theme !== 'tous') vis = vis.filter(t => theme === 'entretien' ? estEntretien(t) : (t.labels || []).includes(theme) || n(t.content + ' ' + t.description).includes(theme));
const cl = n(e.client).trim();
if (cl) vis = vis.filter(t => n(t.content + ' ' + t.description).includes(cl));
if (!vis.length) return [{ json: { resultat: 'Aucun memo trouve' + (theme && theme !== 'tous' ? ' pour le theme ' + theme : '') + (cl ? ' pour ' + e.client : '') + '.' } }];
vis.sort((a, b) => String(b.added_at || '').localeCompare(String(a.added_at || '')));
const L = vis.slice(0, 40).map(t => {
  const d = String(t.description || '');
  const quand = (d.match(/Dicté le (.+?)(?: à | \()/) || [])[1] || String(t.added_at || '').slice(0, 10);
  const app = (d.match(/\((iPhone[^)]*)\)/i) || [])[1] || '';
  const qui = /klb/i.test(app) ? 'Laurent' : (app ? app.replace(/iphone\s*/i, '') : '?');
  const proche = (d.match(/Client à proximité au moment du mémo : ([^.]+)\./) || [])[1];
  const lbl = (t.labels || []).filter(x => !['memo'].includes(x)).join(', ');
  return '- ' + t.content + ' | note par ' + qui + ' le ' + quand + (t.due ? ' | pour le ' + t.due.date : '') + (proche ? ' | client proche suggere : ' + proche : '') + (lbl ? ' | ' + lbl : '') + ' | ' + (NOMS[t.project_id] || '');
});
return [{ json: { resultat: 'Memos non coches (' + vis.length + ') :\n' + L.join('\n') + (vis.length > 40 ? '\n(40 premiers seulement)' : '') } }];
